// ════════════════════════════════════════════════════════════════
// Agent Tests L0 V1.0 — Deterministe — Analyse statique
// Verifie que le code genere est deployable avant Code Review/QA/SAST
// Tests: existence fichiers, equilibre braces, patterns requis, securite
// ════════════════════════════════════════════════════════════════
const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body
           : (typeof raw.body === 'string') ? JSON.parse(raw.body.replace(/^=+/, '').trim()) : raw;

const task_id  = String(body.task_id || 'unknown');
const language = String(body.language || 'javascript');
const files    = Array.isArray(body.files) ? body.files : [];

const results    = [];
let globalStatus = 'PASS';

function fail(test, msg, file, fix) {
  results.push({ test, status: 'FAIL', message: msg, file: file || null, fix: fix || null });
  globalStatus = 'FAIL';
}
function warn(test, msg, file, fix) {
  results.push({ test, status: 'WARN', message: msg, file: file || null, fix: fix || null });
}
function pass(test, file) {
  results.push({ test, status: 'PASS', file: file || null });
}

// ─────────────────────────────────────────────
// TEST L0-01 : server.js existe
// ─────────────────────────────────────────────
const serverFile = files.find(f => f.path && f.path.replace(/\\/g,'/').split('/').pop() === 'server.js');
if (!serverFile) {
  fail('L0-01-SERVER_EXISTS',
    'server.js introuvable dans les fichiers generes.',
    null,
    'Verifier que Agent Backend renvoie bien files[] avec un fichier server.js');
} else {
  pass('L0-01-SERVER_EXISTS', 'server.js');

  const code = String(serverFile.content || '');

  // ─────────────────────────────────────────────
  // TEST L0-02 : Equilibre accolades/parentheses
  // ─────────────────────────────────────────────
  let braces = 0, parens = 0, brackets = 0;
  let inStr = false, strChar = '', escaped = false;
  let inLineComment = false, inBlockComment = false;

  // Compteur robuste : ignore les commentaires (// et /* */) pour ne pas etre
  // piege par des apostrophes/parentheses dans du texte commente.
  for (let i = 0; i < code.length; i++) {
    const c = code[i];
    const nx = code[i + 1];
    if (inLineComment) { if (c === '\n') inLineComment = false; continue; }
    if (inBlockComment) { if (c === '*' && nx === '/') { inBlockComment = false; i++; } continue; }
    if (escaped) { escaped = false; continue; }
    if (c === '\\' && inStr) { escaped = true; continue; }
    if (!inStr && c === '/' && nx === '/') { inLineComment = true; i++; continue; }
    if (!inStr && c === '/' && nx === '*') { inBlockComment = true; i++; continue; }
    if (!inStr && (c === '"' || c === "'" || c === '`')) { inStr = true; strChar = c; continue; }
    if (inStr && c === strChar) { inStr = false; continue; }
    if (inStr) continue;
    if (c === '{') braces++; else if (c === '}') braces--;
    else if (c === '(') parens++; else if (c === ')') parens--;
    else if (c === '[') brackets++; else if (c === ']') brackets--;
  }
  if (braces !== 0)    fail('L0-02-BALANCED_BRACES',   'Accolades non equilibrees (delta: ' + braces + ')', 'server.js', braces > 0 ? 'Accolade fermante } manquante' : 'Accolade ouvrante { manquante');
  else                 pass('L0-02-BALANCED_BRACES', 'server.js');
  if (parens !== 0)    fail('L0-02-BALANCED_PARENS',   'Parentheses non equilibrees (delta: ' + parens + ')', 'server.js', parens > 0 ? 'Parenthese fermante ) manquante' : 'Parenthese ouvrante ( manquante');
  else                 pass('L0-02-BALANCED_PARENS', 'server.js');
  if (brackets !== 0)  warn('L0-02-BALANCED_BRACKETS', 'Crochets non equilibrees (delta: ' + brackets + ')', 'server.js', 'Verifier les tableaux et acces aux proprietes');
  else                 pass('L0-02-BALANCED_BRACKETS', 'server.js');

  // ─────────────────────────────────────────────
  // TEST L0-03 : require('express') present
  // ─────────────────────────────────────────────
  if (code.indexOf("require('express')") < 0 && code.indexOf('require("express")') < 0) {
    fail('L0-03-EXPRESS_IMPORTED', 'require("express") introuvable dans server.js. Serveur ne demarrera pas.', 'server.js', 'Ajouter: const express = require("express");');
  } else { pass('L0-03-EXPRESS_IMPORTED', 'server.js'); }

  // ─────────────────────────────────────────────
  // TEST L0-04 : app.listen() present
  // ─────────────────────────────────────────────
  if (code.indexOf('app.listen') < 0) {
    fail('L0-04-APP_LISTEN', 'app.listen() introuvable. Le serveur ne demarrera jamais.', 'server.js', 'Ajouter: app.listen(PORT, () => console.log("Server on port " + PORT));');
  } else { pass('L0-04-APP_LISTEN', 'server.js'); }

  // ─────────────────────────────────────────────
  // TEST L0-05 : Endpoint /health present
  // ─────────────────────────────────────────────
  if (code.indexOf('/health') < 0) {
    warn('L0-05-HEALTH_ENDPOINT',
      'Endpoint GET /health absent. L Agent Monitoring ne pourra pas verifier l etat.',
      'server.js',
      "Ajouter: app.get('/health', (req, res) => res.json({ status: 'ok' }));");
  } else { pass('L0-05-HEALTH_ENDPOINT', 'server.js'); }

  // ─────────────────────────────────────────────
  // TEST L0-06 : PORT dynamique (pas hardcode)
  // ─────────────────────────────────────────────
  const listenIdx = code.indexOf('app.listen(');
  if (listenIdx >= 0) {
    const snippet = code.slice(listenIdx, listenIdx + 40);
    const portMatch = snippet.match(/app\.listen\(\s*(\d{4,5})/);
    if (portMatch) {
      warn('L0-06-PORT_HARDCODED', 'PORT hardcode a ' + portMatch[1] + '. Utiliser process.env.PORT.', 'server.js', 'const PORT = process.env.PORT || 3000; app.listen(PORT, ...)');
    } else { pass('L0-06-DYNAMIC_PORT', 'server.js'); }
  }

  // ─────────────────────────────────────────────
  // TEST L0-07 : Pas d'eval()
  // ─────────────────────────────────────────────
  if (code.indexOf('eval(') >= 0) {
    fail('L0-07-NO_EVAL', 'eval() detecte dans server.js. Vulnerabilite critique (OWASP A03).', 'server.js', 'Supprimer eval() et remplacer par une alternative securisee');
  } else { pass('L0-07-NO_EVAL', 'server.js'); }

  // ─────────────────────────────────────────────
  // TEST L0-08 : try/catch present
  // ─────────────────────────────────────────────
  if (code.indexOf('try {') < 0 && code.indexOf('try{') < 0) {
    warn('L0-08-ERROR_HANDLING', 'Aucun bloc try/catch detecte. Les erreurs runtime causeront un crash.', 'server.js', 'Entourer les blocs critiques: try { } catch(e) { res.status(500).json({error: e.message}) }');
  } else { pass('L0-08-ERROR_HANDLING', 'server.js'); }

  // ─────────────────────────────────────────────
  // TEST L0-09 : express.static present (sert le frontend)
  // ─────────────────────────────────────────────
  if (code.indexOf('express.static') < 0) {
    warn('L0-09-STATIC_MIDDLEWARE', 'express.static() absent. Le frontend HTML ne sera pas servi.', 'server.js', "Ajouter: app.use(express.static('public'));");
  } else { pass('L0-09-STATIC_MIDDLEWARE', 'server.js'); }
}

// ─────────────────────────────────────────────
// TEST L0-10 : package.json valide
// ─────────────────────────────────────────────
const pkgFile = files.find(f => f.path && f.path.replace(/\\/g,'/').split('/').pop() === 'package.json');
if (!pkgFile) {
  warn('L0-10-PACKAGE_JSON', 'package.json introuvable. npm install ne pourra pas s executer.', null, 'Verifier que Agent Backend genere bien un package.json');
} else {
  try {
    // Strip le prefixe "// FILE: package.json\n" ajoute par le Backend
    const cleaned = (pkgFile.content || '{}').replace(/^\/\/[^\n]*\n/, '').trim();
    const pkg = JSON.parse(cleaned);
    const deps = Object.keys(pkg.dependencies || {});
    if (!deps.includes('express')) {
      fail('L0-10-PACKAGE_JSON_DEPS', 'express manquant dans package.json dependencies.', 'package.json', 'Ajouter "express" dans dependencies');
    } else { pass('L0-10-PACKAGE_JSON', 'package.json'); }
  } catch(e) {
    fail('L0-10-PACKAGE_JSON_INVALID', 'package.json invalide (JSON malforme): ' + e.message, 'package.json', 'Corriger la syntaxe JSON du package.json genere');
  }
}

// ─────────────────────────────────────────────
// TEST L0-11 : index.html present
// ─────────────────────────────────────────────
const htmlFile = files.find(f => f.path && (f.path.indexOf('index.html') >= 0 || f.path.indexOf('app.js') >= 0));
if (!htmlFile) {
  warn('L0-11-FRONTEND_EXISTS', 'index.html / app.js absent. Frontend peut etre manquant.', null, 'Verifier que Agent Frontend genere bien les fichiers publics');
} else { pass('L0-11-FRONTEND_EXISTS', htmlFile.path); }

const passCount = results.filter(r => r.status === 'PASS').length;
const failCount = results.filter(r => r.status === 'FAIL').length;
const warnCount = results.filter(r => r.status === 'WARN').length;

return [{
  json: {
    _version: '1.0',
    agent: 'Agent Tests L0',
    task_id,
    tests_l0_status: globalStatus,
    tests_count: results.length,
    pass_count:  passCount,
    fail_count:  failCount,
    warn_count:  warnCount,
    results,
    summary: globalStatus === 'FAIL'
      ? 'FAIL — ' + failCount + ' test(s) bloquant(s). Le ZIP ne demarre pas correctement. Pipeline arrete.'
      : 'PASS — ' + passCount + '/' + results.length + ' tests OK' + (warnCount > 0 ? ', ' + warnCount + ' warning(s)' : '') + '.',
    checked_at: new Date().toISOString()
  }
}];
